import sqlite3
from datetime import datetime

import stripe

DB_PATH = "recruiting.db"


def _prorated_refund(amount_cents, paid_at):
    days = (datetime.utcnow() - datetime.fromisoformat(paid_at)).days
    if days <= 7:
        return amount_cents
    if days <= 30:
        return amount_cents // 2
    return 0


def refund_assessment_fee(assessment_id, reason):
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            "SELECT id, candidate_id, payment_intent_id, amount_cents, paid_at, refund_status "
            "FROM assessments WHERE id = ?",
            (assessment_id,),
        ).fetchone()
        if row is None:
            return {"error": f"assessment {assessment_id} not found"}
        if row["refund_status"] == "refunded":
            return {"error": "assessment fee already refunded"}

        refund_cents = _prorated_refund(row["amount_cents"], row["paid_at"])
        if refund_cents == 0:
            return {"assessment_id": assessment_id, "refunded_cents": 0, "note": "outside refund window"}

        refund = stripe.Refund.create(
            payment_intent=row["payment_intent_id"],
            amount=refund_cents,
            metadata={"assessment_id": str(assessment_id), "candidate_id": str(row["candidate_id"])},
        )
        conn.execute(
            "UPDATE assessments SET refund_status = 'refunded', refund_id = ?, refunded_cents = ?, "
            "refund_reason = ?, refunded_at = ? WHERE id = ?",
            (refund.id, refund_cents, reason, datetime.utcnow().isoformat(), assessment_id),
        )
        conn.commit()
        return {
            "assessment_id": assessment_id,
            "candidate_id": row["candidate_id"],
            "refund_id": refund.id,
            "refunded_cents": refund_cents,
            "status": refund.status,
        }
    finally:
        conn.close()
